from pathlib import Path
def write(out:Path):
 html='''<!doctype html><meta charset=utf-8><title>Sprint 14 Timeline Audit</title><style>body{background:#09111f;color:#eef2ff;font:15px system-ui;margin:auto;max-width:1200px;padding:18px}video{width:100%;background:#000}.track{height:52px;display:flex;overflow:hidden;margin:8px 0}.b{min-width:2px;border-right:1px solid #0f172a;background:#16a34a}.m{background:#dc2626}button{padding:9px;margin:5px}#now{background:#17243a;padding:10px}</style><h1>Sprint 14 — Continuous Timeline Audit</h1><video id=v controls src="./SPRINT14_SYNC_DRAFT_720P.mp4"></video><div class=track id=track></div><div id=now></div><button id=prev>Previous Manual Issue</button><button id=next>Next Manual Issue</button><p>Green = APPROVED · Red = MANUAL FIX</p><script>let p;const v=document.getElementById('v'),E=x=>document.getElementById(x);fetch('./TIMELINE_PLAN.json').then(x=>x.json()).then(x=>{p=x;let d=p.duration_ms;E('track').innerHTML=p.presentation_slots.map(s=>`<div class="b ${s.approval_state==='MANUAL_FIX'?'m':''}" style="width:${100*(s.timeline_end_ms-s.timeline_start_ms)/d}%" title="${s.beat_id} ${s.presentation_type}"></div>`).join('');show()});function show(){if(!p)return;let t=v.currentTime*1000,s=p.presentation_slots.find(x=>x.timeline_start_ms<=t&&t<x.timeline_end_ms);E('now').textContent=s?`${s.beat_id} · ${s.presentation_type} · ${s.approval_state} · ${s.exact_narration}`:'Timeline end'}v.ontimeupdate=show;function jump(dir){let ms=p.presentation_slots.filter(x=>x.approval_state==='MANUAL_FIX'),t=v.currentTime*1000,x=dir>0?ms.find(x=>x.timeline_start_ms>t+100):[...ms].reverse().find(x=>x.timeline_start_ms<t-100);if(!x)x=dir>0?ms[0]:ms[ms.length-1];v.currentTime=x.timeline_start_ms/1000;show()}E('next').onclick=()=>jump(1);E('prev').onclick=()=>jump(-1)</script>''';(out/'SPRINT14_TIMELINE_REVIEW.html').write_text(html,encoding='utf8');(out/'START_SPRINT14_TIMELINE_REVIEW.bat').write_text('@echo off\r\ncd /d "'+str(out)+'"\r\nstart "Sprint14Server" /min python -m http.server 8774 --bind 127.0.0.1\r\ntimeout /t 2 /nobreak >nul\r\nstart "" http://127.0.0.1:8774/SPRINT14_TIMELINE_REVIEW.html\r\n',encoding='ascii')
